    // Find order
    guard let orderIndex = orders.firstIndex(where: { $0.id == id }) else { return .sendFailed }
    let order = orders[orderIndex]

    // Optimistically move to "waiting" in the UI.
    await MainActor.run {
        orders[orderIndex].status = .waitingForCustomer
    }

    // Generate 6-digit OTP
    let otpCode = String(format: "%06d", Int.random(in: 0...999999))

    // Update database: stamp associate_id AND save pickup_code
    do {
        var updates: [String: AnyJSON] = ["pickup_code": .string(otpCode)]
        if let associateID {
            updates["associate_id"] = .string(associateID.uuidString)
