        try await SupabaseManager.shared.client
            .from("orders")
            .update(updates)
            .eq("id", value: id)
            .execute()
    } catch {
        print("Error updating pickup code and associate_id on pack: \(error)")
        await loadData(storeID: lastLoadedStoreID)
        return .sendFailed
    }

    // Send Email via Resend if email exists
    guard let email = order.customerEmail, !email.isEmpty else {
        await loadData(storeID: lastLoadedStoreID)
        return .noEmail
    }

    let resendApiKey = "re_3ot8yx3s_BDYPp6FcxJXDcFsSXU6bGW7t"
    guard let url = URL(string: "https://api.resend.com/emails") else { return .sendFailed }
    var request = URLRequest(url: url)
    request.httpMethod = "POST"
    request.setValue("Bearer \(resendApiKey)", forHTTPHeaderField: "Authorization")
    request.setValue("application/json", forHTTPHeaderField: "Content-Type")

    let htmlBody = """
    <div style="font-family: sans-serif; max-width: 600px; margin: 0 auto; color: #333;">
        <h2 style="color: #6a0d45;">Your order is ready for pickup!</h2>
        <p>Hi \(order.customerName),</p>
        <p>Your BOPIS order <strong>\(order.orderId)</strong> is now packed and ready to be collected at the store.</p>
        <div style="background-color: #f9f9f9; padding: 20px; border-radius: 8px; text-align: center; margin: 30px 0;">
            <p style="margin: 0; color: #666; font-size: 14px; text-transform: uppercase;">Your Secure Pickup Code</p>
            <h1 style="margin: 10px 0 0 0; font-size: 42px; letter-spacing: 5px; color: #000;">\(otpCode)</h1>
        </div>
        <p>Please show this code to the Sales Associate when you arrive.</p>
        <p>Thank you,<br>Nexus Retail</p>
    </div>
    """

    let payload: [String: Any] = [
        "from": "Nexus Retail <receipts@resend.dev>",
        "to": [email],
        "subject": "Ready for Pickup: Order \(order.orderId)",
        "html": htmlBody
    ]

    do {
        request.httpBody = try JSONSerialization.data(withJSONObject: payload)
        let (data, response) = try await URLSession.shared.data(for: request)
        if let httpRes = response as? HTTPURLResponse, (200...299).contains(httpRes.statusCode) {
            await loadData(storeID: lastLoadedStoreID)
            return .emailed
        } else {
            print("Resend email failed: \(String(data: data, encoding: .utf8) ?? "")")
            await loadData(storeID: lastLoadedStoreID)
            return .sendFailed
        }
    } catch {
        print("Failed to send BOPIS email: \(error)")
        await loadData(storeID: lastLoadedStoreID)
        return .sendFailed
    }
}

