func verifyAndCollect(id: UUID, code: String) async -> Bool {
    do {
        struct PickupCodeRow: Decodable { let pickup_code: String? }
        let row: PickupCodeRow = try await SupabaseManager.shared.client
            .from("orders")
            .select("pickup_code")
            .eq("id", value: id)
            .single()
            .execute()
            .value

        if row.pickup_code == code {
            // Update status to collected
            try await SupabaseManager.shared.client
                .from("orders")
                .update(["status": "collected"])
                .eq("id", value: id)
                .execute()

            if let index = orders.firstIndex(where: { $0.id == id }) {
                await MainActor.run { orders[index].status = .collected }
            }
            return true
        }
        return false
    } catch {
        print("verify_pickup_code failed: \(error)")
        return false
    }
}

